/**
 * Ticket price phases ("early bird", "presale", "regular", ...) of a paid
 * event (owner request 2026-10-17). Pure, unit-tested; mirrored for the app in
 * lib/features/ticket_payments/domain/price_phases.dart (display + editor
 * validation; THIS file decides what is sold and at which price).
 *
 * events/{id}.pricePhases (organizer-written, optional):
 *   ordered list (max MAX_PRICE_PHASES) of
 *   { id (stable, generated by the app), nameKey (PHASE_NAME_KEYS, each once),
 *     price (MAJOR units of the event currency, like events.price),
 *     quantity (int >= 1: tickets sold at that price) }
 *   Prices strictly increase phase by phase, every price within the event
 *   price limits (PHASE_PRICE_MIN..MAX), and when the event has a capacity
 *   (maxAttendees > 0) the quantities add up to at most that capacity.
 *
 * ticket_inventory/event_{id} (server-only, the doc that already holds the
 * seat holds; signed-in users may `get` it to show "N left at this price"):
 *   phaseSold  { phaseId: n }   tickets RESERVED at that phase = open orders
 *                               holding seats + paid orders. Reserved in the
 *                               createTicketCheckout transaction, released
 *                               exactly where seats are released (expire /
 *                               cancel / reject / supersede / refund /
 *                               dispute), re-added on a late payment.
 *   phaseLocks { phaseId: unitMinor }  the price (minor units) the phase was
 *                               first reserved at; refreshed while the phase
 *                               has no reservations.
 *
 * The CURRENT phase is the first one (in list order = price order) with
 * tickets left. An order for N tickets takes them from the current phase on
 * and may span phases (2 left at early bird + 1 at regular). When every phase
 * is sold out the event is sold out for ticket sales (the event capacity is
 * still checked as an extra limit).
 *
 * Editing after sales start (checked here at every checkout, because the
 * organizer writes the event doc directly; firestore.rules only checks the
 * shape and the price order): a phase with reservations cannot be removed,
 * its price cannot change and its quantity cannot go below what it sold; new
 * phases go after the last phase that has sold. A setup that breaks these is
 * never sold from (`price_phases_invalid`).
 */
import { toMinor } from './currency';

export const PHASE_NAME_KEYS = [
  'superEarlyBird', 'earlyBird', 'presale', 'regular', 'late', 'lastMinute', 'door',
] as const;
export type PhaseNameKey = typeof PHASE_NAME_KEYS[number];

export const MAX_PRICE_PHASES = 10;
/** Same limits as the event price itself (app editor 1..1000, major units). */
export const PHASE_PRICE_MIN = 1;
export const PHASE_PRICE_MAX = 1000;
export const PHASE_MAX_QUANTITY = 100000;
const PHASE_ID_RE = /^[A-Za-z0-9_-]{1,40}$/;

export interface PricePhase {
  id: string;
  nameKey: PhaseNameKey;
  /** Major units of the event currency. */
  price: number;
  quantity: number;
}

/** One line of an order: [quantity] tickets of the phase at [unitAmount] (minor units). */
export interface PhaseLine {
  phaseId: string;
  nameKey: PhaseNameKey;
  unitAmount: number;
  quantity: number;
}

export type PhaseCounts = Record<string, number>;

/** Raw event field -> phases; null when the event has no phases (absent / empty / not a list). */
export function readPricePhases(raw: unknown): unknown[] | null {
  if (!Array.isArray(raw) || raw.length === 0) return null;
  return raw;
}

/**
 * Structural validation of an event's phases (both the app and the server):
 * returns the phases or a reason code. [capacity] = maxAttendees (<= 0 = unlimited).
 */
export function validatePricePhases(
  raw: unknown[], capacity: number, currency: string,
): { ok: true; phases: PricePhase[] } | { ok: false; reason: string } {
  if (raw.length > MAX_PRICE_PHASES) return { ok: false, reason: 'too_many_phases' };
  const phases: PricePhase[] = [];
  const ids = new Set<string>();
  const names = new Set<string>();
  let prevMinor = -1;
  let total = 0;
  for (const p of raw as any[]) {
    if (!p || typeof p !== 'object') return { ok: false, reason: 'invalid_phase' };
    const { id, nameKey, price, quantity } = p;
    if (typeof id !== 'string' || !PHASE_ID_RE.test(id) || ids.has(id)) return { ok: false, reason: 'invalid_phase_id' };
    if (typeof nameKey !== 'string' || !(PHASE_NAME_KEYS as readonly string[]).includes(nameKey)) {
      return { ok: false, reason: 'invalid_phase_name' };
    }
    if (names.has(nameKey)) return { ok: false, reason: 'duplicate_phase_name' };
    if (typeof price !== 'number' || !Number.isFinite(price) || price < PHASE_PRICE_MIN || price > PHASE_PRICE_MAX) {
      return { ok: false, reason: 'phase_price_out_of_range' };
    }
    if (!Number.isInteger(quantity) || quantity < 1 || quantity > PHASE_MAX_QUANTITY) {
      return { ok: false, reason: 'invalid_phase_quantity' };
    }
    const minor = toMinor(price, currency);
    if (minor <= prevMinor) return { ok: false, reason: 'phase_prices_not_increasing' };
    prevMinor = minor;
    ids.add(id);
    names.add(nameKey);
    total += quantity;
    phases.push({ id, nameKey: nameKey as PhaseNameKey, price, quantity });
  }
  if (capacity > 0 && total > capacity) return { ok: false, reason: 'phases_exceed_capacity' };
  return { ok: true, phases };
}

const n0 = (v: unknown) => Math.max(0, Math.floor(Number(v) || 0));

/**
 * Editing rules after sales started, against the server counters: a phase
 * with reservations exists, keeps its locked price and has at least as many
 * tickets as it reserved; a phase that never sold (no lock) is not placed
 * before a phase that has reservations. Reason code or null.
 */
export function phaseEditError(phases: PricePhase[], sold: PhaseCounts, locks: PhaseCounts, currency: string): string | null {
  const byId = new Map(phases.map((p) => [p.id, p]));
  for (const [id, n] of Object.entries(sold || {})) {
    if (n0(n) === 0) continue;
    const p = byId.get(id);
    if (!p) return 'phase_with_sales_removed';
    const lock = locks?.[id];
    if (lock !== undefined && lock !== null && toMinor(p.price, currency) !== Number(lock)) return 'phase_with_sales_price_changed';
    if (p.quantity < n0(n)) return 'phase_quantity_below_sold';
  }
  let lastSold = -1;
  phases.forEach((p, i) => { if (n0(sold?.[p.id]) > 0) lastSold = i; });
  for (let i = 0; i < lastSold; i++) {
    const id = phases[i].id;
    if (!(locks && id in locks)) return 'phase_inserted_before_sold';
  }
  return null;
}

/** Tickets left per phase (never negative). */
export function phasesLeft(phases: PricePhase[], sold: PhaseCounts): number[] {
  return phases.map((p) => Math.max(0, p.quantity - n0(sold?.[p.id])));
}

/** Index of the current phase (first with tickets left), -1 when every phase is sold out. */
export function currentPhaseIndex(phases: PricePhase[], sold: PhaseCounts): number {
  return phasesLeft(phases, sold).findIndex((x) => x > 0);
}

/**
 * Takes [qty] tickets from the current phase on (each ticket priced at its
 * phase). Null when the phases do not have [qty] tickets left.
 */
export function allocatePhases(phases: PricePhase[], sold: PhaseCounts, qty: number, currency: string): PhaseLine[] | null {
  const left = phasesLeft(phases, sold);
  let need = qty;
  const out: PhaseLine[] = [];
  for (let i = 0; i < phases.length && need > 0; i++) {
    const take = Math.min(left[i], need);
    if (take <= 0) continue;
    out.push({ phaseId: phases[i].id, nameKey: phases[i].nameKey, unitAmount: toMinor(phases[i].price, currency), quantity: take });
    need -= take;
  }
  return need > 0 ? null : out;
}

/** Sum of phaseLines quantities per phase (for releases). */
export function phaseLineCounts(lines: unknown): PhaseCounts {
  const out: PhaseCounts = {};
  if (!Array.isArray(lines)) return out;
  for (const l of lines as any[]) {
    if (!l || typeof l.phaseId !== 'string') continue;
    const q = n0(l.quantity);
    if (q > 0) out[l.phaseId] = (out[l.phaseId] || 0) + q;
  }
  return out;
}

/** Preset phase names for provider checkout lines, by the buyer's language. */
const NAMES: Record<string, Record<PhaseNameKey, string>> = {
  en: { superEarlyBird: 'Super early bird', earlyBird: 'Early bird', presale: 'Presale', regular: 'Regular', late: 'Late', lastMinute: 'Last minute', door: 'At the door' },
  de: { superEarlyBird: 'Super Early Bird', earlyBird: 'Early Bird', presale: 'Vorverkauf', regular: 'Regulär', late: 'Spät', lastMinute: 'Last Minute', door: 'Abendkasse' },
  es: { superEarlyBird: 'Súper anticipada', earlyBird: 'Anticipada', presale: 'Preventa', regular: 'General', late: 'Tardía', lastMinute: 'Último minuto', door: 'En la puerta' },
  fr: { superEarlyBird: 'Super early bird', earlyBird: 'Early bird', presale: 'Prévente', regular: 'Normal', late: 'Tardif', lastMinute: 'Dernière minute', door: 'Sur place' },
  it: { superEarlyBird: 'Super early bird', earlyBird: 'Early bird', presale: 'Prevendita', regular: 'Intero', late: 'Ultimi biglietti', lastMinute: 'Last minute', door: 'Alla porta' },
  pt: { superEarlyBird: 'Super antecipado', earlyBird: 'Antecipado', presale: 'Pré-venda', regular: 'Normal', late: 'Tardio', lastMinute: 'Última hora', door: 'Na porta' },
};

export function phaseName(nameKey: string, locale?: string | null): string {
  const lang = (locale || 'en').slice(0, 2).toLowerCase();
  const t = NAMES[lang] || NAMES.en;
  return (t as Record<string, string>)[nameKey] ?? NAMES.en[nameKey as PhaseNameKey] ?? 'Ticket';
}
